   for(int pos=1;pos<=10;pos++){PolicySpecR27 p=SetIntersectionPolicyR30.spec(pos,32,128,IdeaFamilyR27.meta("I14","RESEARCH",0,0,"FIXED_SET_RESEARCH"));ReplayEvaluatorR27.Trace tr=FusionStudyR30R1.trace(p,c);int available=0,act=0,hits=0,singleHits=0,common=0;List<Object> support=new ArrayList<>();for(int t=c.split.selectFrom;t<c.split.selectTo;t++){Map<String,Object> s=SetIntersectionPolicyR30.support(c.cache,t,pos,32,128);if(!"BLOCKED_HISTORY_OR_GAP".equals(s.get("status")))available++;int a=((Number)s.get("sourceAMask")).intValue();if(a!=0&&(a&(1<<(c.data.draws[t][pos-1]-1)))!=0)singleHits++;if(!tr.skipped[t]){act++;hits+=tr.hit[t];if((a&(1<<(c.data.draws[t][pos-1]-1)))!=0)common++;}if(support.size()<3&&t>=c.split.selectTo-3)support.add(s);}Map<String,Object> row=point("P"+pos,available==0?null:act/(double)available,available,"合法K3覆盖率；不足3弃权，随机同大小K3命中基线0.30");row.put("singleSetHits",singleHits);row.put("intersectionActs",act);row.put("intersectionHits",hits);row.put("hitRate",act==0?null:hits/(double)act);row.put("abstentions",available-act);row.put("missedSingleSetHits",singleHits-common);row.put("lastSupport",support);row.put("stack",available==0?null:Arrays.asList(act,available-act));f.put("series",Arrays.asList("支持K3的期数","不足3或条件不符而弃权的期数"));row.put("randomK3ExpectedHits",.3*act);points(f).add(row);}return f;
