public static void consume(ResearchWriteQueueR27.Batch batch,String proposal,String child,int generation,String consumer,long now){
        ResearchContractR30R1.sha(proposal);ResearchContractR30R1.sha(child);
        batch.guardBefore(db->{try(Cursor c=db.rawQuery("SELECT p.state,p.payload_json,p.payload_hash,r.role,r.source_revision,r.source_commit,r.summary_json,r.dataset_hash FROM r30r1_proposal p JOIN r30r1_analysis_run r ON r.run_id=p.run_id WHERE p.proposal_id=?",new String[]{proposal})){if(!c.moveToFirst()||!"READY".equals(c.getString(0))||ResearchInputPinR30R1.revision(db,c.getString(7))!=c.getLong(4))throw new StaleResearch();if(!com.ethk3.novaonepro.BuildConfig.SOURCE_COMMIT_R26.equals(c.getString(5)))throw new StaleResearch();Object sourceSummary=JsonR27.parse(c.getString(6));if(!(sourceSummary instanceof Map)||!(((Map<?,?>)sourceSummary).get("sourceContract") instanceof Map)||!FrozenConfirmationR30.currentSemantics().equals(((Map<?,?>)((Map<?,?>)sourceSummary).get("sourceContract")).get("abi")))throw new StaleResearch();if(!"SELECT".equals(c.getString(3))||!StatsR27.sha256(c.getString(1)).equals(c.getString(2)))return -1;Object p=JsonR27.parse(c.getString(1));return p instanceof Map&&child.equals(((Map<?,?>)p).get("candidateHash"))?0:-1;}});
        String receipt=ResearchContractR30R1.hash(proposal+'|'+child+'|'+generation+'|'+consumer);
        batch.add("INSERT INTO r30r1_consume VALUES(?,?,?,?,?,?)",proposal,child,generation,consumer,receipt,now);
        batch.add("UPDATE r30r1_proposal SET state='CONSUMED' WHERE proposal_id=? AND state='READY'",proposal);
        final com.ethk3.novaonepro.DatabaseCoordinator.WriteCallable<Integer> original=batch.after;
        batch.after=db->{try(Cursor c=db.rawQuery("SELECT spec_json,state FROM r27_policy WHERE policy_hash=?",new String[]{child})){if(!c.moveToFirst()||!"BORN".equals(c.getString(1))||!PolicySpecR27.parse(c.getString(0)).policyHash().equals(child))throw new IllegalStateException("RESEARCH_CONSUMPTION_REQUIRES_ACTUAL_BORN_CHILD");}
            try(Cursor source=db.rawQuery("SELECT run_id,payload_json FROM r30r1_proposal WHERE proposal_id=?",new String[]{proposal})){if(!source.moveToFirst())throw new StaleResearch();Map<?,?> payload=(Map<?,?>)JsonR27.parse(source.getString(1));java.util.Set<String> runs=new java.util.LinkedHashSet<>();runs.add(source.getString(0));if(payload.get("sourceRuns") instanceof java.util.List)for(Object run:(java.util.List<?>)payload.get("sourceRuns"))runs.add(ResearchContractR30R1.sha(String.valueOf(run)));if(runs.size()>4)throw new IllegalStateException("RESEARCH_SOURCE_REFERENCE_BUDGET");for(String run:runs){try(Cursor proof=db.rawQuery("SELECT dataset_hash,role,source_revision,source_commit,summary_json,from_ordinal,through_ordinal FROM r30r1_analysis_run WHERE run_id=? AND status='COMMITTED'",new String[]{run})){if(!proof.moveToFirst()||!"SELECT".equals(proof.getString(1))||!currentSource(proof.getString(3),proof.getString(4)))throw new StaleResearch();ResearchInputPinR30R1.require(db,proof.getString(0),proof.getLong(2));Map<String,Object> link=new LinkedHashMap<>();link.put("proposalId",proposal);link.put("childPolicyHash",child);link.put("consumer",consumer);link.put("generation",generation);link.put("receiptHash",receipt);link.put("scope","ACTUAL_ORIGINAL_BORN_CHILD_SAME_TRANSACTION_NOT_QUALITY_PROOF");db.execSQL("INSERT OR IGNORE INTO r30r1_research_measure VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",new Object[]{run,"CONSUMED_BY:"+proposal,"RESEARCH_SOURCE_CONSUMPTION",child,"ORIGINAL_BIRTH_GATE_RECEIPT",proof.getLong(5),proof.getLong(6),0,null,null,null,JsonR27.write(link)});}}}
            return original==null?0:original.call(db);};
    }

