static List<Panel> load(SQLiteDatabase db,int group,CancellationSignal cancel){
        List<ResearchGraphSpecsR30R1.Spec> specs=ResearchGraphSpecsR30R1.group(group);Map<String,Panel> found=new HashMap<>();
        String[] args=new String[specs.size()];StringBuilder marks=new StringBuilder();for(int i=0;i<args.length;i++){args[i]=specs.get(i).id;if(i>0)marks.append(',');marks.append('?');}
        String sql="SELECT c.view_id,c.payload_json,c.payload_hash,r.dataset_hash,r.role,r.through_ordinal,c.run_id FROM r30r1_chart_cache c JOIN r30r1_analysis_run r ON r.run_id=c.run_id WHERE c.view_id IN ("+marks+") AND c.frame_id=(SELECT n.frame_id FROM r30r1_chart_cache n WHERE n.view_id=c.view_id ORDER BY n.updated_at DESC,n.frame_id LIMIT 1) ORDER BY c.view_id LIMIT 6";
        String error=null;
        try(Cursor c=db.rawQuery(sql,args,cancel)){
            while(c.moveToNext())for(ResearchGraphSpecsR30R1.Spec spec:specs)if(spec.id.equals(c.getString(0))){
                try{String payload=c.getString(1);if(payload==null||payload.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>262144)throw new IllegalStateException("FRAME_BYTE_BUDGET");if(!ResearchContractR30R1.hash(payload).equals(c.getString(2)))throw new IllegalStateException("FRAME_HASH_MISMATCH");
                    @SuppressWarnings("unchecked") Map<String,Object> frame=(Map<String,Object>)JsonR27.parse(payload);
                    found.put(spec.id,panel(spec,frame,c.getString(3),c.getString(4),c.getLong(5),c.getString(6)));
                }catch(RuntimeException malformed){found.put(spec.id,missing(spec,"READ_ERROR",malformed.getClass().getSimpleName()+":"+String.valueOf(malformed.getMessage())));}
            }
        }catch(OperationCanceledException cancelled){throw cancelled;}catch(RuntimeException missing){error=missing.getClass().getSimpleName();}
        List<Panel> out=new ArrayList<>();for(ResearchGraphSpecsR30R1.Spec spec:specs)out.add(found.containsKey(spec.id)?found.get(spec.id):missing(spec,error==null?"WAITING_ANALYSIS":"BLOCKED_SOURCE",error==null?"尚无已提交分析产物；不能以统计行数代替分析":error));return out;
    }

static Panel panel(ResearchGraphSpecsR30R1.Spec s,Map<String,Object> f,String dataset,String role,long through,String run){
        List<Point> points=new ArrayList<>();List<Edge> edges=new ArrayList<>();
        if("R06".equals(s.id)&&f.containsKey("mean")){
            long n=f.get("evaluatedIssues") instanceof Number?((Number)f.get("evaluatedIssues")).longValue():-1;
            points.add(new Point(String.valueOf(f.get("componentPath")),number(f.get("mean")),number(f.get("lower95")),number(f.get("upper95")),n,"研究配对贡献；"+f.get("reason")+"；proposal="+f.get("proposalId")));
        }else{
            Object raw=f.get("points");if(!(raw instanceof List))return missing(s,"INSUFFICIENT_ANALYSIS_FRAME","缺少points；生产者须输出对象级分析结果");
            if(((List<?>)raw).size()>MAX_POINTS)throw new IllegalArgumentException("RESEARCH_FRAME_REQUIRES_PAGINATION");
            for(Object row:(List<?>)raw){Map<String,Object> p=(Map<String,Object>)row;long n=p.get("n") instanceof Number?((Number)p.get("n")).longValue():-1;
                double[] stack=null;if(p.get("stack") instanceof List){List<?> v=(List<?>)p.get("stack");if(v.size()>12)throw new IllegalArgumentException("RESEARCH_SERIES_LIMIT");stack=new double[v.size()];for(int i=0;i<stack.length;i++)stack[i]=number(v.get(i));}
                points.add(new Point(String.valueOf(p.get("label")),number(p.get("value")),number(p.get("lower")),number(p.get("upper")),n,String.valueOf(p.get("details")),number(p.get("open")),number(p.get("expected")),stack));
            }
            if(f.get("edges") instanceof List){List<?> rows=(List<?>)f.get("edges");if(rows.size()>MAX_EDGES)throw new IllegalArgumentException("RESEARCH_EDGE_PAGINATION");for(Object row:rows){Map<?,?> e=(Map<?,?>)row;edges.add(new Edge(String.valueOf(e.get("from")),String.valueOf(e.get("to")),String.valueOf(e.get("label"))));}}
        }
        List<String> series=new ArrayList<>();if(f.get("series") instanceof List)for(Object x:(List<?>)f.get("series"))series.add(String.valueOf(x));
        String note="用途："+s.measure+"\n算法消费者："+s.consumer+"\n实效验收："+s.verification+"\n角色="+role+"；run="+run+"；dataset="+dataset+"。研究图不授予REAL资格。";
        boolean any=false;for(Point p:points){any|=Double.isFinite(p.value);if(p.stack!=null)for(double v:p.stack)any|=Double.isFinite(v);}if("GRAPH".equals(s.kind))any=!points.isEmpty();
        if(f.get("modelReplayPerformance")!=null)note+="\n模型前后版本配对："+JsonR27.write(f.get("modelReplayPerformance"));String status=f.get("status") instanceof String?(String)f.get("status"):any?"MEASURED_RESEARCH_ONLY":"INSUFFICIENT";note+="\n当前产物："+status+(f.get("reason")==null?"":"；"+f.get("reason"))+"\n分析角色不是质量证书；负值和区间跨零如实保留。";String kind=s.kind;if(kind.equals("HEATMAP")&&(!(f.get("matrixRows") instanceof List)||!(f.get("matrixColumns") instanceof List)))kind="BAR";
        Panel panel=new Panel("research-workbench",s.id+" "+s.title,kind,"r30r1_research_measure/"+s.measure,"输入截至ordinal="+through,note,status,points,edges,Collections.singletonList(0.0),series);if(f.get("matrixRows") instanceof List&&f.get("matrixColumns") instanceof List){List<String> rows=new ArrayList<>(),cols=new ArrayList<>();for(Object x:(List<?>)f.get("matrixRows"))rows.add(String.valueOf(x));for(Object x:(List<?>)f.get("matrixColumns"))cols.add(String.valueOf(x));return new Panel(panel,rows,cols);}return panel;
    }

public static Map<String,Object> compute(String view,EvalContextR27 c,List<PolicySpecR27> population,long revision){
  if(c.labels!=c.data.draws||c.split.selectFrom>=c.split.selectTo)throw new IllegalArgumentException("OBSERVATORY_ORIGINAL_SELECT_REQUIRED");Map<String,Object> f=header(view,c);List<PolicySpecR27> ps=supported(population);PolicySpecR27 first=ps.isEmpty()?null:ps.get(0);
  if(view.equals("R01")||view.equals("R02")){
   StructureStudyR30R1.Product product=StructureStudyR30R1.compute(c,ResearchContractR30R1.Role.SELECT);Map<String,Object> original=(Map<String,Object>)JsonR27.parse(view.equals("R01")?product.statePayload:product.errorPayload);f.putAll(original);
   for(Object o:(List<?>)original.get("cells")){Map<String,Object> cell=(Map<String,Object>)o;String label="W"+cell.get("window")+":"+cell.get("target")+(cell.containsKey("position")?":P"+cell.get("position"):"");Map<String,Object> p=point(label,cell.get(view.equals("R01")?"value":"meanPairedGain"),cell.get(view.equals("R01")?"supportCalendarIssues":"calendarIssues") instanceof Number?((Number)cell.get(view.equals("R01")?"supportCalendarIssues":"calendarIssues")).longValue():0,JsonR27.write(cell));p.put("lower",cell.get("lower95"));p.put("upper",cell.get("upper95"));points(f).add(p);}
   if(view.equals("R01")){List<Object> ordered=new ArrayList<>();List<String> rowNames=new ArrayList<>(),columns=new ArrayList<>();for(int pos=1;pos<=10;pos++)columns.add("P"+pos);for(int window:StructureStudyR30R1.WINDOWS)for(String target:StructureStudyR30R1.TARGETS){rowNames.add("W"+window+":"+target);for(int pos=1;pos<=10;pos++)for(Object o:points(f))if(((Map<?,?>)o).get("label").equals("W"+window+":"+target+":P"+pos))ordered.add(o);}f.put("points",ordered);f.put("matrixRows",rowNames);f.put("matrixColumns",columns);}
   else {TreeMap<Long,List<Object>> byBlock=new TreeMap<>();List<String> series=new ArrayList<>();int at=0;for(Object o:(List<?>)original.get("cells")){Map<String,Object> cell=(Map<String,Object>)o;series.add("W"+cell.get("window")+":"+cell.get("target"));for(Object raw:(List<?>)cell.get("blocks")){Map<?,?> block=(Map<?,?>)raw;long start=((Number)block.get("fromOrdinal")).longValue();List<Object> values=byBlock.computeIfAbsent(start,k->new ArrayList<>(Collections.nCopies(12,null)));if(Boolean.TRUE.equals(block.get("included")))values.set(at,block.get("meanGain"));}at++;}List<Object> rows=new ArrayList<>();for(Map.Entry<Long,List<Object>> e:byBlock.entrySet()){Map<String,Object> row=point("ordinal:"+e.getKey(),e.getValue().get(0),64,"固定64期块；缺失/尾块断线；各系列 aggregate CI与loss目标见原cells");row.put("stack",e.getValue());rows.add(row);}f.put("points",rows);f.put("series",series);f.put("xAxis","PREDECLARED_CALENDAR_BLOCK_START_ORDINAL");}
   return f;
  }
  if(view.equals("R03")){
   MatrixTensorR30R1.Tensor a=MatrixResearchR30R1.build("NUMBER_POSITION_COMPATIBILITY",c,null,revision),b=MatrixResearchR30R1.build("CROSS_POSITION_FLOW",c,null,revision);f.put("numberPosition",JsonR27.parse(a.payload));f.put("directedLag",JsonR27.parse(b.payload));f.put("sourceHashes",Arrays.asList(a.hash,b.hash));
   for(int pos=1;pos<=10;pos++)for(int src=1;src<=10;src++){int n=0,match=0;for(int t=c.split.selectFrom;t<c.split.selectTo;t++)if(c.data.consecutive(t,1)){n++;if(c.data.draws[t][pos-1]==c.data.draws[t-1][src-1])match++;}points(f).add(point("P"+src+"@1→P"+pos,n==0?null:match/(double)n-.1,n,"原SELECT同类滞后超额关联；不是因果或自然优势证书"));}return f;
  }
  if(view.equals("R04")){
   for(int pos=1;pos<=10;pos++){PolicySpecR27 p=SetIntersectionPolicyR30.spec(pos,32,128,IdeaFamilyR27.meta("I14","RESEARCH",0,0,"FIXED_SET_RESEARCH"));ReplayEvaluatorR27.Trace tr=FusionStudyR30R1.trace(p,c);int available=0,act=0,hits=0,singleHits=0,common=0;List<Object> support=new ArrayList<>();for(int t=c.split.selectFrom;t<c.split.selectTo;t++){Map<String,Object> s=SetIntersectionPolicyR30.support(c.cache,t,pos,32,128);if(!"BLOCKED_HISTORY_OR_GAP".equals(s.get("status")))available++;int a=((Number)s.get("sourceAMask")).intValue();if(a!=0&&(a&(1<<(c.data.draws[t][pos-1]-1)))!=0)singleHits++;if(!tr.skipped[t]){act++;hits+=tr.hit[t];if((a&(1<<(c.data.draws[t][pos-1]-1)))!=0)common++;}if(support.size()<3&&t>=c.split.selectTo-3)support.add(s);}Map<String,Object> row=point("P"+pos,available==0?null:act/(double)available,available,"合法K3覆盖率；不足3弃权，随机同大小K3命中基线0.30");row.put("singleSetHits",singleHits);row.put("intersectionActs",act);row.put("intersectionHits",hits);row.put("hitRate",act==0?null:hits/(double)act);row.put("abstentions",available-act);row.put("missedSingleSetHits",singleHits-common);row.put("lastSupport",support);row.put("stack",available==0?null:Arrays.asList(act,available-act));f.put("series",Arrays.asList("支持K3的期数","不足3或条件不符而弃权的期数"));row.put("randomK3ExpectedHits",.3*act);points(f).add(row);}return f;
