   PolicySpecR27 p=null;for(PolicySpecR27 x:ps)if(x.ast.op.equals("add")&&x.ast.kids.length==2){p=x;break;}if(p==null)return blocked(f,"LEGAL_TWO_COMPONENT_ADD_PARENT_REQUIRED");PolicySpecR27 a=p.withAst(p.ast.kids[0],p.meta),b=p.withAst(p.ast.kids[1],p.meta);if(!FailureProfileR30.legal(a)||!FailureProfileR30.legal(b))return blocked(f,"SINGLE_ARMS_MUST_RETAIN_TYPED_POLICY_CONTRACT");ReplayEvaluatorR27.Trace ab=FusionStudyR30R1.trace(p,c),ta=FusionStudyR30R1.trace(a,c),tb=FusionStudyR30R1.trace(b,c);ResearchGainR30R1 synergy=new ResearchGainR30R1(c.data.ordinals[c.split.selectFrom],c.data.ordinals[c.split.selectTo-1],64,4,200);double[] sums=new double[4];int n=0;double[] uniform=new double[10];Arrays.fill(uniform,.1);
